14	// A fetch mock whose promises stay pending until `resolve()` is called
15	// explicitly, and which honors AbortSignal like real fetch (rejects with an
16	// AbortError and stops counting as in-flight the moment its signal aborts).
17	// Tracks the high-water mark of concurrently in-flight calls so a test can
18	// assert the "at most one in flight" invariant directly, not just infer it
19	// from call counts.
20	function controllableFetch() {
21	  const calls = [];
22	  let inFlight = 0;
23	  let maxInFlight = 0;
24	  const fetchMock = vi.fn((url, options) => {
25	    inFlight++;
26	    maxInFlight = Math.max(maxInFlight, inFlight);
27	    return new Promise((resolve, reject) => {
28	      const entry = { url, options, settled: false };
29	      entry.resolve = (value) => {
30	        if (entry.settled) return;
31	        entry.settled = true;
32	        inFlight--;
33	        resolve(value);
34	      };
35	      options.signal.addEventListener("abort", () => {
36	        if (entry.settled) return;
37	        entry.settled = true;
38	        inFlight--;
39	        reject(Object.assign(new Error("Aborted"), { name: "AbortError" }));
40	      });
41	      calls.push(entry);
42	    });
43	  });
44	  return { fetchMock, calls, getMaxInFlight: () => maxInFlight };
45	}
