import { readFileSync } from "node:fs";

const load = (path) =>
  JSON.parse(readFileSync(path, "utf8"))
    .result.map((s) => (typeof s === "string" ? JSON.parse(s) : s))
    .sort((a, b) => a.at - b.at);

const p = (arr, q) => {
  if (!arr.length) return null;
  const s = [...arr].sort((a, b) => a - b);
  return s[Math.min(s.length - 1, Math.floor(q * s.length))];
};

// Split into runs on >60s idle, return the largest one.
function biggestRun(samples) {
  const runs = [];
  let start = 0;
  for (let i = 1; i <= samples.length; i++) {
    if (i !== samples.length && samples[i].at - samples[i - 1].at <= 60_000)
      continue;
    runs.push(samples.slice(start, i));
    start = i;
  }
  return runs.sort((a, b) => b.length - a.length)[0];
}

function stats(label, run) {
  const gaps = [];
  for (let i = 1; i < run.length; i++) gaps.push(run[i].at - run[i - 1].at);
  const live = gaps.filter((g) => g <= 60_000);
  const span = run[run.length - 1].at - run[0].at;
  const mb1 = run.filter((s) => s.musicBrainzCalls === 1).length;
  const mb2 = run.filter((s) => s.musicBrainzCalls === 2).length;
  const floor = (mb1 * 1100 + mb2 * 2200) / run.length;
  const ms = run.map((s) => s.ms);
  return {
    label,
    n: run.length,
    spanSec: Math.round(span / 1000),
    // THE number: wall-clock seconds per artist end-to-end
    throughput: Math.round(span / (run.length - 1)),
    cadenceP50: p(live, 0.5),
    cadenceP90: p(live, 0.9),
    durP50: p(ms, 0.5),
    durP90: p(ms, 0.9),
    durP99: p(ms, 0.99),
    floor: Math.round(floor),
    oneCallPct: Math.round((mb1 / run.length) * 100),
  };
}

const before = stats("before (sequential)", biggestRun(load(process.argv[2])));
const after = stats("after  (pool of 4)", biggestRun(load(process.argv[3])));

const rows = [
  ["artists", "n"],
  ["run span (s)", "spanSec"],
  ["ms/artist end-to-end", "throughput"],
  ["cadence p50", "cadenceP50"],
  ["cadence p90", "cadenceP90"],
  ["duration p50", "durP50"],
  ["duration p90", "durP90"],
  ["duration p99", "durP99"],
  ["lock floor", "floor"],
  ["1-call share %", "oneCallPct"],
];
console.log(
  `${"metric".padEnd(22)}${"before".padStart(10)}${"after".padStart(10)}${"delta".padStart(12)}`,
);
for (const [name, key] of rows) {
  const b = before[key];
  const a = after[key];
  const d =
    typeof b === "number" && typeof a === "number" && b !== 0
      ? `${a - b > 0 ? "+" : ""}${a - b} (${(((a - b) / b) * 100).toFixed(0)}%)`
      : "";
  console.log(
    `${name.padEnd(22)}${String(b).padStart(10)}${String(a).padStart(10)}${d.padStart(12)}`,
  );
}

// Where did the time actually go? Bucket the gaps.
for (const [label, run] of [
  ["before", biggestRun(load(process.argv[2]))],
  ["after", biggestRun(load(process.argv[3]))],
]) {
  const gaps = [];
  for (let i = 1; i < run.length; i++) gaps.push(run[i].at - run[i - 1].at);
  const buckets = { "<500": 0, "500-1500": 0, "1500-2500": 0, "2500-5000": 0, ">5000": 0 };
  for (const g of gaps) {
    if (g < 500) buckets["<500"]++;
    else if (g < 1500) buckets["500-1500"]++;
    else if (g < 2500) buckets["1500-2500"]++;
    else if (g < 5000) buckets["2500-5000"]++;
    else buckets[">5000"]++;
  }
  const total = gaps.length;
  const timeIn = { "<500": 0, "500-1500": 0, "1500-2500": 0, "2500-5000": 0, ">5000": 0 };
  for (const g of gaps) {
    if (g < 500) timeIn["<500"] += g;
    else if (g < 1500) timeIn["500-1500"] += g;
    else if (g < 2500) timeIn["1500-2500"] += g;
    else if (g < 5000) timeIn["2500-5000"] += g;
    else timeIn[">5000"] += g;
  }
  const spent = Object.values(timeIn).reduce((a, b) => a + b, 0);
  console.log(`\n${label}: gap distribution (n=${total})`);
  for (const k of Object.keys(buckets)) {
    console.log(
      `  ${k.padEnd(10)} ${String(buckets[k]).padStart(4)} gaps (${((buckets[k] / total) * 100).toFixed(0)}%)   holds ${((timeIn[k] / spent) * 100).toFixed(0)}% of total time`,
    );
  }
}

